'use strict';
const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Fictional election model. Lean is an illustrative Republican-minus-Democratic margin, not live polling.
const raw=[['AL','Alabama',9,26,6,7],['AK','Alaska',3,15,8,0],['AZ','Arizona',11,2,5,1],['AR','Arkansas',6,24,5,5],['CA','California',54,-24,4,0],['CO','Colorado',10,-12,4,2],['CT','Connecticut',7,-15,3,10],['DE','Delaware',3,-16,4,10],['DC','District of Columbia',3,-75,5,10],['FL','Florida',30,8,7,8],['GA','Georgia',16,1,6,8],['HI','Hawaii',4,-25,8,1],['ID','Idaho',4,30,2,1],['IL','Illinois',19,-13,3,6],['IN','Indiana',11,16,3,7],['IA','Iowa',6,10,3,5],['KS','Kansas',6,17,4,4],['KY','Kentucky',8,24,4,7],['LA','Louisiana',8,20,6,5],['ME','Maine',4,-7,0,11],['MD','Maryland',10,-28,4,9],['MA','Massachusetts',11,-30,2,10],['MI','Michigan',15,0,2,7],['MN','Minnesota',10,-5,1,5],['MS','Mississippi',6,17,6,6],['MO','Missouri',10,16,4,5],['MT','Montana',4,18,1,2],['NE','Nebraska',5,20,3,4],['NV','Nevada',6,1,3,1],['NH','New Hampshire',4,-4,1,10],['NJ','New Jersey',14,-13,3,9],['NM','New Mexico',5,-10,5,2],['NY','New York',28,-20,2,9],['NC','North Carolina',16,3,5,8],['ND','North Dakota',3,32,1,3],['OH','Ohio',17,8,3,8],['OK','Oklahoma',7,33,5,4],['OR','Oregon',8,-14,3,0],['PA','Pennsylvania',19,0,2,8],['RI','Rhode Island',4,-20,2,11],['SC','South Carolina',9,12,5,9],['SD','South Dakota',3,26,2,3],['TN','Tennessee',11,24,5,7],['TX','Texas',40,8,6,3],['UT','Utah',6,23,3,2],['VT','Vermont',3,-30,1,9],['VA','Virginia',13,-6,4,8],['WA','Washington',12,-18,2,0],['WV','West Virginia',4,38,4,6],['WI','Wisconsin',10,0,2,6],['WY','Wyoming',3,42,2,2]];
const states=raw.map(([id,name,ev,lean,y,x],i)=>({id,name,ev,lean,y,x:Math.round(x),delegates:ev*7,priority:i%5}));
const primaryGroups=[['IA'],['NH'],['NV'],['SC'],['CA','TX','NC','VA','MA','MN','CO','AL','TN','OK','UT','VT','AR'],['MI','WA','ID','MO','MS','HI'],['FL','OH','IL','AZ','KS','LA'],['NY','PA','MD','DE','CT','RI','WI'],['IN','NE','WV','KY','OR'],['GA','NJ','NM','SD','MT','ND','AK','WY','ME','DC']];
const issues=[{name:'Health care',labels:['Universal public coverage','Public option + private plans','Expand subsidies','Market competition','Reduce federal role'],hint:'Public coverage energizes the left; market policies appeal to the right.'},{name:'Taxes & the economy',labels:['Wealth tax + large public investment','Raise top rates; invest in workers','Targeted middle-class tax relief','Lower business taxes','Broad tax cuts + spending cuts'],hint:'Your economic plan shapes voter alignment across states.'},{name:'Climate & energy',labels:['Rapid fossil fuel phaseout','Clean-energy investment','Gradual transition + mixed energy','Expand domestic oil and gas','Roll back energy regulations'],hint:'Climate ambition helps in blue states; energy production helps in red states.'},{name:'Immigration',labels:['Expand legal routes + broad legalization','Legalization + border funding','Bipartisan border and visa reform','Stricter enforcement + legal routes','Mass deportations + tight entry limits'],hint:'Immigration positions influence ideological fit and general-election appeal.'},{name:'Guns',labels:['Ban assault weapons + strict licensing','Universal background checks','Background checks + gun rights','Protect ownership; limited checks','Remove most federal restrictions'],hint:'State electorates differ in their preferred balance of gun rights and regulation.'},{name:'Education',labels:['Free public college + federal funding','Expand school and college aid','Local flexibility + targeted aid','Expand charter and school choice','Vouchers + smaller federal role'],hint:'Education choices shape your coalition and contrast with your opponents.'}];
const backgrounds=[{name:'Senator',icon:'▥',desc:'A national network and a record to defend.',money:11,power:.16,trust:2},{name:'House member',icon:'▤',desc:'Grassroots roots. Ready for a bigger stage.',money:7,power:.12,trust:5},{name:'Governor',icon:'⚑',desc:'Executive experience and a strong home base.',money:9,power:.15,trust:4},{name:'Businessperson',icon:'◈',desc:'A deep war chest and an outsider message.',money:20,power:.03,trust:-3},{name:'Community organizer',icon:'✳',desc:'People-powered energy on a lean budget.',money:5,power:.2,trust:6},{name:'Military veteran',icon:'★',desc:'Service, credibility, and cross-party appeal.',money:8,power:.1,trust:7}];
const stories=[{name:'Working-class roots',desc:'Stronger organizing; +2 starting trust.',trust:2,field:.5},{name:'Built a successful company',desc:'Your network contributes an extra $4M.',money:4},{name:'A lifetime of public service',desc:'Experience gives +4 starting trust.',trust:4},{name:'A reformer taking on insiders',desc:'An energized launch gives +0.12 momentum.',power:.12}];
let g;try{g=JSON.parse(localStorage.getItem('road270-v1'))}catch{}if(!g||g.version!==1)g=fresh();
function fresh(){return {version:1,screen:0,name:'Alex Morgan',party:'D',home:'MI',background:0,story:0,age:45,experience:10,careerDetail:'',trait:0,ideology:-1,issues:[1,1,1,1,1,1]}}
function save(){localStorage.setItem('road270-v1',JSON.stringify(g))}function commit(){save();render()}
function foot(){return '<p class="fine">A fictional strategy game, not an election forecast. Rivals, polls, calendar, delegate rules, and campaign effects are simulated. All 50 states + DC; 538 electoral votes. Maine and Nebraska use statewide winner-take-all for this game. Progress saves in this browser.</p><footer><span>ROAD TO 270 / CAMPAIGN LAB</span><span>Build a coalition. Earn every vote.</span></footer>'}
function steps(){return '<div class="steps">'+['Your candidate','Your platform','The primaries','General election'].map((t,i)=>`<div class="step ${Math.min(g.screen,3)===i?'active':''}">0${i+1} &nbsp; ${t}</div>`).join('')+'</div>'}
function render(){const a=$('#app');a.innerHTML=steps()+(g.screen===0?setup():g.screen===1?platform():g.screen===4?result():campaign())+foot();bind()}
function setup(){return `<section class="hero"><div><div class="eyebrow">A country to convince. A campaign to build.</div><h1>Your name.<br>Your platform.<br>The White House.</h1><p>Start with a story. Find your coalition. Turn a long-shot campaign into a path to the presidency.</p><span class="pill">01 / BUILD YOUR CANDIDATE</span></div><div class="hero-art"><div class="seal">★<small>THE ROAD STARTS HERE</small><div style="font-size:30px;margin-top:12px">270</div></div></div></section><div class="formgrid panel"><div><label for="name">CANDIDATE NAME</label><input id="name" maxlength="35" value="${esc(g.name)}"></div><div><label for="party">PARTY</label><select id="party"><option value="D" ${g.party==='D'?'selected':''}>Democratic Party</option><option value="R" ${g.party==='R'?'selected':''}>Republican Party</option></select></div><div><label for="home">HOME STATE</label><select id="home">${states.filter(s=>s.id!=='DC').map(s=>`<option value="${s.id}" ${g.home===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div><label for="ideology">POLITICAL SPECTRUM · <span id="ideolabel">${g.party==='R'&&g.ideology<.4?'Centrist Republican':ideolabel(g.ideology)}</span></label><input type="range" id="ideology" min="${g.party==='R'?0:-2}" max="${g.party==='R'?2:0}" step=".25" value="${g.ideology}"><div class="range-ends"><span>${g.party==='R'?'Centrist Republican':'Progressive'}</span><span>${g.party==='R'?'Center-right':'Center-left'}</span><span>${g.party==='R'?'Conservative':'Centrist Democrat'}</span></div></div></div><h2 style="margin-top:30px">What brought you here?</h2><p class="muted">Choose your experience. Every starting advantage comes with a tradeoff.</p><div class="grid">${backgrounds.map((b,i)=>`<button class="choice ${g.background===i?'selected':''}" data-bg="${i}" aria-pressed="${g.background===i}"><span class="icon">${b.icon}</span><strong>${b.name}</strong><small>${b.desc}</small><span class="pill" style="margin-top:14px">$${b.money}M starting funds · ${b.trust>=0?'+':''}${b.trust} trust</span></button>`).join('')}</div><h3 style="margin-top:28px">Choose your backstory</h3><div class="formgrid">${stories.map((s,i)=>`<button class="choice ${g.story===i?'selected':''}" data-story="${i}" aria-pressed="${g.story===i}"><strong>${s.name}</strong><small>${s.desc}</small></button>`).join('')}</div><div class="footerbar"><span class="muted">Home-state support follows you through both elections.</span><button id="next">Build my platform →</button></div>`}
function ideolabel(n){return n< -1.4?'Progressive':n<-.4?'Center-left':n<.4?'Centrist':n<1.4?'Center-right':'Conservative'}
function platform(){return `<div class="hero" style="margin-bottom:25px"><div><div class="eyebrow">02 / MAKE YOUR CASE</div><h1>What do you<br>stand for?</h1><p>Policies change your appeal in every state. Staying close to your declared ideology builds trust; moving toward the center can broaden your general-election coalition.</p></div><div class="panel"><h3>${esc(g.name)} · ${g.party==='D'?'Democrat':'Republican'}</h3><p class="muted">${backgrounds[g.background].name} from ${states.find(s=>s.id===g.home).name}<br>${stories[g.story].name}</p><span class="pill">${g.party==='R'&&g.ideology<.4?'Centrist Republican':ideolabel(g.ideology)}</span><p id="fitnote" style="font-size:12px;margin:15px 0 0">${fitnote()}</p></div></div><div class="issues">${issues.map((v,i)=>`<div class="panel issue"><label for="issue${i}">0${i+1} / ${v.name.toUpperCase()}</label><select id="issue${i}" data-issue="${i}">${v.labels.map((x,j)=>g.party==='R'&&j<2?'':`<option value="${j}" ${g.issues[i]===j?'selected':''}>${x}</option>`).join('')}</select><p>${v.hint}</p></div>`).join('')}</div><div class="footerbar"><button class="secondary" id="back">← Candidate</button><button id="launch">Announce my campaign →</button></div>`}
function policy(){return g.issues.reduce((a,v)=>a+v-2,0)/6}function fitnote(){const d=Math.abs(policy()-g.ideology);return `Platform: ${ideolabel(policy())}. Message consistency: ${d<.6?'strong':d<1.2?'mixed':'weak'} (${Math.round(100-d*20)}%).`}
function launch(){const b=backgrounds[g.background],s=stories[g.story];Object.assign(g,{screen:2,round:0,money:b.money+(s.money||0),power:1.3+b.power+(s.power||0),trust:clamp(65+b.trust+(s.trust||0)-Math.abs(policy()-g.ideology)*8,30,95),actions:3,field:{[g.home]:1+(s.field||0)},local:{},calls:{},delegates:[0,0,0,0],selected:'IA',events:[],eventDone:false,log:['Your campaign is official. Three actions remain before the first contest.'],rivals:g.party==='D'?[{name:'Sen. Jordan Ellis',ideol:-1.7,power:1.53,color:'#567fba'},{name:'Gov. Cameron Brooks',ideol:-.5,power:1.5,color:'#bd8c4b'},{name:'Rep. Taylor Chen',ideol:-1.1,power:1.45,color:'#9276ad'}]:[{name:'Gov. Casey Bennett',ideol:1.7,power:1.53,color:'#bd6a60'},{name:'Sen. Morgan Reed',ideol:.6,power:1.5,color:'#bd8c4b'},{name:'CEO Riley Grant',ideol:1.2,power:1.45,color:'#9276ad'}]});commit()}
function voters(s,primary=true){return clamp(primary?(g.party==='D'?-1.0:1.1)+s.lean/85:s.lean/60,-1.9,1.9)}
function affinity(s,p){return g.issues.reduce((a,v,i)=>a+Math.abs(v-2-clamp(p+Math.sin((s.priority+1)*(i+1))*.3,-2,2)),0)/6}
function primaryShares(s,noise=false){const ideal=voters(s),pfit=affinity(s,ideal),home=g.home===s.id?.42:0;let weights=[Math.max(.1,g.power+.005*(g.trust-65)+home+(g.field[s.id]||0)*.10+(g.local[s.id]||0)-pfit*.24-Math.abs(g.ideology-ideal)*.08),...g.rivals.map((r,i)=>Math.max(.1,r.power-Math.abs(r.ideol-ideal)*.32+Math.sin(s.ev*(i+1))*.10))];if(noise)weights=weights.map(v=>Math.max(.05,v+rand(-.18,.18)));let t=weights.reduce((a,b)=>a+b,0);return weights.map(v=>v/t*100)}
function generalMargin(s){const dir=g.party==='D'?-1:1,ideal=voters(s,false);const player=affinity(s,ideal),opp=Math.abs(g.opponent.ideol-ideal);let rmargin=s.lean;const boost=(opp-player)*4+(g.power-1.8)*4+(g.trust-65)*.15+(g.field[s.id]||0)*.9+(g.local[s.id]||0)*3+(g.home===s.id?4:0)-(g.opponent.home===s.id?3:0);return clamp(dir*rmargin+boost,-90,90)}
const colorYou=()=>g.party==='D'?'#3c79b3':'#bc5b51';
function currentGroup(){return g.screen===2?primaryGroups[g.round]:[]}
function estimateEV(){return states.reduce((a,s)=>a+(generalMargin(s)>0?s.ev:0),0)}
function campaign(){const primary=g.screen===2,group=currentGroup(),total=states.reduce((a,s)=>a+s.delegates,0),target=Math.floor(total/2)+1,names=[g.name,...g.rivals.map(r=>r.name)],sum=g.delegates.reduce((a,b)=>a+b,0);return `<div class="topline"><div><div class="eyebrow">${primary?'03 / THE NOMINATION':'04 / THE GENERAL ELECTION'}</div><h2 style="margin-bottom:5px">${primary?['The opening test','New Hampshire speaks','The western test','The southern test','Super Tuesday','The coalition takes shape','The big-state battle','The eastern corridor','The final stretch','Last chance for delegates'][g.round]:['A new race begins','Battleground season','The national debate','The closing argument'][g.round]}</h2><span class="muted">${primary?`Round ${g.round+1} of 10 · Next: ${group.join(', ')}`:`Week ${g.round+1} of 4 · Facing ${g.opponent.name}`}</span></div><span class="pill">${esc(g.name)} / ${g.party==='D'?'DEMOCRATIC':'REPUBLICAN'} CAMPAIGN</span></div><div class="stats"><div class="stat"><small>${primary?'Delegates earned':'Projected electoral votes'}</small><strong>${primary?g.delegates[0]:estimateEV()}</strong> <span class="muted">/ ${primary?target:270}</span></div><div class="stat"><small>Campaign funds</small><strong>$${g.money.toFixed(1)}M</strong></div><div class="stat"><small>Trust / credibility</small><strong>${Math.round(g.trust)}%</strong></div><div class="stat"><small>Actions remaining</small><strong>${g.actions}</strong> <span class="muted">/ 3</span></div></div><div class="dashboard"><div><section class="panel"><div class="topline"><div><h3>${primary?'The delegate map':'The electoral battlefield'}</h3><span class="muted" style="font-size:12px">Click a state to scout it and target your campaign.</span></div><span class="pill">${primary?`${sum} / ${total} awarded`:'270 TO WIN'}</span></div><div class="map">${states.map(s=>{const call=g.calls[s.id],sh=primary?primaryShares(s):null,lead=primary?sh.indexOf(Math.max(...sh)):generalMargin(s)>=0?0:1,colors=primary?[colorYou(),...g.rivals.map(r=>r.color)]:[colorYou(),g.party==='D'?'#bc5b51':'#3c79b3'];let col=call?call.color:colors[lead];let alpha=call?'ff':primary?'45':Math.abs(generalMargin(s))>15?'bb':Math.abs(generalMargin(s))>5?'77':'35';return `<button class="state ${g.selected===s.id?'target':''}" style="grid-row:${s.y+1};grid-column:${s.x+1};background:${col}${alpha};color:${call?'white':'#173c43'}" data-state="${s.id}" title="${s.name}${call?' · '+esc(call.winner):''}">${s.id}<small>${primary?s.delegates:s.ev}</small></button>`}).join('')}</div><div class="map-key"><span><i class="dot" style="background:${colorYou()}"></i>You</span>${primary?g.rivals.map(r=>`<span><i class="dot" style="background:${r.color}"></i>${r.name.split(' ').slice(-1)}</span>`).join(''):`<span><i class="dot" style="background:${g.party==='D'?'#bc5b51':'#3c79b3'}"></i>${g.opponent.name}</span>`}<span>${primary?'Solid = voted · pale = polling leader':'Darker = stronger lead'}</span></div><div class="detail">${stateDetail()}</div></section><section class="panel" style="margin-top:18px"><h3>${primary?'The nomination standings':'The road to the White House'}</h3>${primary?`<p class="muted" style="font-size:11px">${g.party==='D'?'Proportional delegates; 15% state threshold.':'Winner-take-all delegates in each state.'} Majority required. At a contested convention, the lowest candidate transfers delegates to their nearest ideological ally until someone wins.</p>`+names.map((n,i)=>`<div class="row" style="font-size:12px"><span>${esc(n)} ${i===0?'(you)':''}</span><b>${g.delegates[i]} delegates</b></div><div class="bar"><span style="width:${g.delegates[i]/target*100}%;background:${i===0?colorYou():g.rivals[i-1].color}"></span></div>`).join(''):`<div class="row"><span>You: ${estimateEV()} EV</span><span>${g.opponent.name}: ${538-estimateEV()} EV</span></div><div class="countbar"><span style="width:${estimateEV()/538*100}%;background:${colorYou()}"></span><span style="flex:1;background:${g.party==='D'?'#bc5b51':'#3c79b3'}"></span></div><p class="muted" style="font-size:12px">Projected leads are uncertain. A shared national polling error and state surprises can change election night.</p>`}</section></div><aside><section class="panel"><h3>Your next move</h3><p class="muted" style="font-size:12px">Target: <b>${states.find(s=>s.id===g.selected).name}</b>. Each action spends one turn.</p><div class="actions">${[['rally','Hold a rally','$1.5M · local support'],['ads','Run targeted ads','$3M · larger local boost'],['field','Build a field office','$2M · lasting state support'],['fundraise','Fundraise','+$4M · trust cost −1'],['message','National speech','$2M · nationwide momentum'],['listen','Listening tour','Free · +4 credibility']].map(([id,title,desc])=>`<button class="action" data-action="${id}" ${g.actions===0||((primary&&g.calls[g.selected])&&['rally','ads','field'].includes(id))?'disabled':''}>${title}<small>${desc}</small></button>`).join('')}</div>${eventUI()}<button class="wide" id="advance" style="margin-top:20px">${primary?'Hold '+(g.round===9?'final contests':'next contests')+' →':g.round===3?'Start election night →':'Advance campaign week →'}</button><p style="font-size:10px;margin:8px 0 0" class="muted">Unused actions expire. ${primary?'Each round brings $2M in contributions.':'Each week brings $3M in contributions.'}</p></section><section class="panel" style="margin-top:18px"><h3>Campaign dispatch</h3><div class="log" aria-live="polite">${g.log.slice().reverse().map(t=>`<p>${esc(t)}</p>`).join('')}</div></section></aside></div>`}
function stateDetail(){const s=states.find(s=>s.id===g.selected),c=g.calls[s.id];if(c)return `<b>${s.name} · RESULTS</b><br>${esc(c.winner)} won with ${c.share.toFixed(1)}%. ${c.results.map(r=>esc(r.name)+': '+r.share.toFixed(1)+'%'+(r.delegates!==undefined?' / '+r.delegates+' delegates':'')).join(' · ')}`;if(g.screen===2){const sh=primaryShares(s);return `<b>${s.name} · ${s.delegates} delegates · ${currentGroup().includes(s.id)?'VOTING NEXT':'UPCOMING'}</b><br>Estimated vote: You ${sh[0].toFixed(1)}% · ${g.rivals.map((r,i)=>r.name.split(' ').pop()+' '+sh[i+1].toFixed(1)+'%').join(' · ')}<br>Field offices: ${g.field[s.id]||0}${g.home===s.id?' · Your home-state advantage':''}`};const m=generalMargin(s);return `<b>${s.name} · ${s.ev} electoral votes</b><br>Estimated margin: ${m>=0?'You':g.opponent.name} +${Math.abs(m).toFixed(1)} · ${Math.abs(m)<5?'Toss-up':Math.abs(m)<12?'Competitive':'Strong lean'}<br>Field offices: ${g.field[s.id]||0}${g.home===s.id?' · Your home-state advantage':''}`}
const events=[{title:'A moment on the debate stage',text:'A rival challenges your readiness to lead. How do you respond?',opts:[['Talk about your record','trust',3],['Deliver a bold closing argument','power',.10],['Turn the attack back on them','risk',0]]},{title:'The donor dilemma',text:'A major donor offers support, but grassroots activists are watching.',opts:[['Accept the contribution','donor',4],['Decline and rally volunteers','volunteer',.12],['Explain your transparency rules','trust',3]]},{title:'A question of priorities',text:'An economic story dominates the news. Your response can define the week.',opts:[['Explain your economic plan','power',.09],['Meet with local workers','trust',4],['Launch a rapid-response ad','adEvent',.18]]},{title:'Your campaign is in the spotlight',text:'A national interview gives you a chance to reach beyond your base.',opts:[['Emphasize shared priorities','trust',4],['Make an energetic policy pitch','power',.10],['Take a high-risk viral moment','risk',0]]}];
function eventUI(){if(g.eventDone)return '<div class="event"><b style="font-size:12px">Message delivered</b><p style="margin-bottom:0">Your response is shaping this round. Use your remaining actions, then advance.</p></div>';const e=events[g.round%events.length];return `<div class="event"><h3>${e.title}</h3><p>${e.text}</p>${e.opts.map((o,i)=>`<button class="secondary" data-event="${i}">${o[0]}</button>`).join('')}<p style="font-size:10px;margin:7px 0 0">Choose one response. Does not spend an action.</p></div>`}
function note(t){g.log.push(t);if(g.log.length>65)g.log.shift()}
function act(type){if(g.actions<1)return;const s=states.find(s=>s.id===g.selected),cost={rally:1.5,ads:3,field:2,message:2}[type]||0;if(g.money<cost){note('Not enough funds for that action. Fundraise or choose a free listening tour.');commit();return}if(g.screen===2&&g.calls[s.id]&&['rally','ads','field'].includes(type))return;g.money-=cost;g.actions--;if(type==='fundraise'){g.money+=4;g.trust=clamp(g.trust-1,0,100);note('Your donor network brought in $4M. Fundraising time costs 1 trust.')}if(type==='rally'||type==='ads'){let n=type==='ads'?.31:.19;g.local[s.id]=(g.local[s.id]||0)+n;g.power+=.015;note(`${type==='ads'?'Targeted ads reached voters':'A rally built support'} in ${s.name}.`)}if(type==='field'){g.field[s.id]=(g.field[s.id]||0)+1;note(`A new field office opened in ${s.name}. Organizers will stay through November.`)}if(type==='message'){g.power+=.12;note('Your national speech strengthened support across the country.')}if(type==='listen'){g.trust=clamp(g.trust+4,0,100);note('Voter conversations strengthened your credibility by 4 points.')}commit()}
function eventChoice(i){if(g.eventDone)return;const o=events[g.round%events.length].opts[i];g.eventDone=true;if(o[1]==='trust'){g.trust=clamp(g.trust+o[2],0,100);note(o[0]+`: +${o[2]} trust.`)}if(o[1]==='power'){g.power+=o[2];note(o[0]+': your national support improved.')}if(o[1]==='donor'){g.money+=4;g.trust-=4;note('You accepted $4M. The donor controversy costs 4 trust.')}if(o[1]==='volunteer'){g.power+=.12;note('Volunteers rallied behind your independent message.')}if(o[1]==='risk'){let win=Math.random()>.45;g.power+=win?.22:-.14;g.trust+=win?1:-4;note(win?'The clip went viral for the right reasons. Your campaign gains momentum.':'The risky response backfired. Momentum and trust slipped.')}if(o[1]==='adEvent'){if(g.money>=2){g.money-=2;g.power+=.18;note('Your $2M rapid-response ad gave your campaign a national lift.')}else{g.trust-=2;note('The promised ad never aired: insufficient funds. Credibility slipped by 2.')}}commit()}
function allocate(sh,n){let eligible=sh.map(v=>v>=15?v:0),t=eligible.reduce((a,b)=>a+b,0),exact=eligible.map(v=>v/t*n),res=exact.map(Math.floor);let remain=n-res.reduce((a,b)=>a+b,0);exact.map((v,i)=>({i,f:v-res[i]})).sort((a,b)=>b.f-a.f).slice(0,remain).forEach(x=>res[x.i]++);return res}
function advance(){if(g.screen===2){for(const id of currentGroup()){const s=states.find(s=>s.id===id),sh=primaryShares(s,true),w=sh.indexOf(Math.max(...sh)),aw=g.party==='D'?allocate(sh,s.delegates):sh.map((v,i)=>i===w?s.delegates:0);aw.forEach((n,i)=>g.delegates[i]+=n);g.calls[id]={winner:w===0?g.name:g.rivals[w-1].name,color:w===0?colorYou():g.rivals[w-1].color,share:sh[w],results:sh.map((v,i)=>({name:i===0?g.name:g.rivals[i-1].name,share:v,delegates:aw[i]}))};note(`${s.id}: ${g.calls[id].winner} wins; you earn ${aw[0]} delegates (${sh[0].toFixed(1)}%).`)}g.power+=.03;g.rivals.forEach(r=>r.power+=rand(.015,.055));if(g.round===9){convention();return}g.round++;g.selected=primaryGroups[g.round][0];g.money+=2}else{if(g.round===3){election();return}g.round++;g.money+=3;g.power-=.02;note('A new campaign week begins. $3M in new contributions arrived.')}g.actions=3;g.eventDone=false;commit()}
function convention(){let votes=[...g.delegates],total=votes.reduce((a,b)=>a+b,0),ideols=[(policy()+g.ideology)/2,...g.rivals.map(r=>r.ideol)],active=[0,1,2,3];while(Math.max(...votes)<total/2+1&&active.length>1){const low=active.slice().sort((a,b)=>votes[a]-votes[b])[0];active=active.filter(i=>i!==low);const dest=active.slice().sort((a,b)=>Math.abs(ideols[a]-ideols[low])-Math.abs(ideols[b]-ideols[low])||votes[b]-votes[a])[0];votes[dest]+=votes[low];note(`Convention: ${low===0?'your':g.rivals[low-1].name+"'s"} ${votes[low]} delegates transfer to ${dest===0?'you':g.rivals[dest-1].name}, the closest remaining ideological ally.`);votes[low]=0}const w=votes.indexOf(Math.max(...votes));g.conventionVotes=votes;g.nominationWinner=w;if(w!==0){g.screen=4;g.outcome='primary-loss';commit();return}g.screen=3;g.round=0;g.actions=3;g.eventDone=false;g.calls={};g.money+=15;g.power=1.8+(g.power-2)*.4;g.selected='PA';g.opponent={name:g.party==='D'?'Gov. Avery Mitchell':'Sen. Jamie Rivera',ideol:g.party==='D'?.8:-.8,home:g.party==='D'?'FL':'CA'};note('You won the nomination! $15M in party support arrives. The general-election race begins.');commit()}
function election(){const national=rand(-3.5,3.5),dir=g.party==='D'?-1:1;g.ev=0;g.popular=0;g.calls={};let weighted=0;for(const s of states){const m=clamp(generalMargin(s)+national+rand(-3,3),-95,95),win=m>0;g.ev+=win?s.ev:0;weighted+=(50+m/2)*s.ev;g.calls[s.id]={winner:win?g.name:g.opponent.name,color:win?colorYou():g.party==='D'?'#bc5b51':'#3c79b3',share:50+Math.abs(m)/2,margin:m,results:[{name:g.name,share:50+m/2},{name:g.opponent.name,share:50-m/2}]}}g.popular=weighted/538;g.outcome=g.ev>=270?'win':g.ev===269?'tie':'loss';g.screen=4;commit()}
function result(){const prim=g.outcome==='primary-loss',won=g.outcome==='win',tie=g.outcome==='tie';return `<div class="bigresult"><div class="eyebrow">${prim?'THE CONVENTION HAS DECIDED':'ELECTION NIGHT / FINAL RESULTS'}</div><h1>${prim?'A campaign worth running.':won?'Hello, President '+esc(g.name)+'.':tie?'An election on a knife edge.':'The country has decided.'}</h1><p>${prim?`${esc(g.rivals[g.nominationWinner-1].name)} secured the nomination. You earned ${g.delegates[0]} pledged delegates. Try a platform closer to your party’s voters, balance national momentum with state organizing, and revisit your campaign strategy.`:won?`Your coalition carried ${g.ev} electoral votes. From your first rally to the final ballot, you built a winning path to the White House.`:tie?'The Electoral College is tied at 269–269. A contingent election would decide the presidency; this game ends in a tie.':`${g.opponent.name} won with ${538-g.ev} electoral votes. You earned ${g.ev}. A few strategic investments in close states could change your next run.`}</p><button id="again">Run a new campaign ↗</button></div>${prim?`<section class="panel"><h3>Your final delegate count</h3>${[g.name,...g.rivals.map(r=>r.name)].map((n,i)=>`<div class="row"><span>${esc(n)}</span><b>${g.delegates[i]} pledged · ${g.conventionVotes[i]} after convention</b></div>`).join('')}</section>`:`<div class="stats"><div class="stat"><small>Your electoral votes</small><strong>${g.ev}</strong></div><div class="stat"><small>Opponent electoral votes</small><strong>${538-g.ev}</strong></div><div class="stat"><small>States + DC carried</small><strong>${Object.values(g.calls).filter(c=>c.winner===g.name).length}</strong></div><div class="stat"><small>Final credibility</small><strong>${Math.round(g.trust)}%</strong></div></div><section class="panel"><h3>The final map</h3><div class="map">${states.map(s=>`<button class="state" data-state="${s.id}" style="grid-row:${s.y+1};grid-column:${s.x+1};background:${g.calls[s.id].color};color:white" title="${s.name}: ${esc(g.calls[s.id].winner)}">${s.id}<small>${s.ev}</small></button>`).join('')}</div><div class="detail">${stateDetail()}</div><p class="muted" style="font-size:12px">${esc(g.name)}: ${g.ev} EV · ${g.opponent.name}: ${538-g.ev} EV. Click any state for final vote shares.</p></section>`}<section class="panel" style="margin-top:20px"><h3>Your campaign story</h3><p class="muted">${backgrounds[g.background].name} · ${stories[g.story].name} · ${ideolabel(g.ideology)} · ${states.find(s=>s.id===g.home).name}</p><div class="log">${g.log.slice(-15).reverse().map(t=>`<p>${esc(t)}</p>`).join('')}</div></section>`}
function reset(){if(g.screen<2||confirm('Start a new campaign? This replaces your saved game.')){g=fresh();commit();window.scrollTo(0,0)}}
function bind(){document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{capture();g.background=+b.dataset.bg;commit()});document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{capture();g.story=+b.dataset.story;commit()});if($('#ideology'))$('#ideology').oninput=e=>{g.ideology=+e.target.value;$('#ideolabel').textContent=ideolabel(g.ideology);save()};if($('#party'))$('#party').onchange=e=>{g.party=e.target.value;g.ideology=g.party==='D'?-1:1;g.issues=Array(6).fill(g.party==='D'?1:3);capture();commit()};['name','home'].forEach(id=>{if($('#'+id))$('#'+id).onchange=capture});document.querySelectorAll('[data-issue]').forEach(b=>b.onchange=()=>{g.issues[+b.dataset.issue]=+b.value;$('#fitnote').textContent=fitnote();save()});if($('#next'))$('#next').onclick=()=>{capture();g.screen=1;commit();window.scrollTo(0,0)};if($('#back'))$('#back').onclick=()=>{g.screen=0;commit()};if($('#launch'))$('#launch').onclick=()=>{launch();window.scrollTo(0,0)};document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{g.selected=b.dataset.state;commit()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventChoice(+b.dataset.event));if($('#advance'))$('#advance').onclick=()=>{advance();window.scrollTo(0,0)};if($('#again'))$('#again').onclick=reset;$('#reset').onclick=reset}
function capture(){if($('#name'))g.name=$('#name').value.trim().slice(0,35)||'Alex Morgan';if($('#home'))g.home=$('#home').value;save()}

// Candidate detail, transparent advantages, and written campaign encounters.
const traits=[
 {name:'Inspiring speaker',description:'Strong rally answers earn an extra +0.06 local support.',type:'rally'},
 {name:'Policy expert',description:'Trust-building responses earn +1 additional credibility.',type:'trust'},
 {name:'Grassroots builder',description:'Each new field office earns an extra +0.05 local support.',type:'field'},
 {name:'Coalition builder',description:'Launch with +3 credibility across your coalition.',type:'coalition'}
];
function normalizeCandidate(){
 g.age=clamp(Number(g.age)||45,35,85);g.experience=clamp(Number(g.experience)||0,0,g.age-18);g.trait=clamp(Number(g.trait)||0,0,3);g.careerDetail=String(g.careerDetail||'').slice(0,100);
 if(g.screen<2){g.ideology=clamp(g.ideology,g.party==='R'?0:-2,g.party==='R'?2:0);if(g.party==='R')g.issues=g.issues.map(v=>Math.max(2,v));}
}
normalizeCandidate();
function careerLabel(){return ['Senate portfolio or committee','House district and policy focus','State executive achievement','Industry and company experience','Community and organizing cause','Service branch and leadership role'][g.background]}
function candidateExtras(){return `<section class="panel" style="margin-top:24px"><h3>The person behind the campaign</h3><p class="muted" style="font-size:12px">Make your fictional candidate specific. Experience and a signature strength add real bonuses.</p><div class="formgrid"><div><label for="age">AGE · 35–85</label><input id="age" type="number" min="35" max="85" value="${g.age}"></div><div><label for="experience">YEARS IN YOUR CHOSEN CAREER</label><input id="experience" type="number" min="0" max="${g.age-18}" value="${g.experience}"></div><div><label for="careerDetail">${careerLabel().toUpperCase()}</label><input id="careerDetail" maxlength="100" placeholder="E.g., led the veterans’ affairs committee" value="${esc(g.careerDetail)}"><small class="muted">Your detail personalizes encounters; it gives no automatic bonus.</small></div><div><label for="trait">SIGNATURE STRENGTH</label><select id="trait">${traits.map((t,i)=>`<option value="${i}" ${g.trait===i?'selected':''}>${t.name}</option>`).join('')}</select></div></div><div class="detail" id="candidateBonuses">${candidateBonusText()}</div><span class="pill">${g.party==='R'?'Republican ideology: centrist → conservative':'Democratic ideology: progressive → centrist'}</span></section>`}
function candidateBonusText(){let b=backgrounds[g.background],s=stories[g.story];return `<b>Your starting advantages</b><br>${b.name}: $${b.money}M, ${signed(b.trust)} credibility, +${b.power.toFixed(2)} national support.<br>${s.name}: ${s.desc}<br>${g.experience} years of experience: +${Math.min(4,Math.floor(g.experience/5))} credibility. ${traits[g.trait].description}`}
function signed(n){return (n>=0?'+':'')+n}
const originalSetup=setup;
setup=function(){let html=originalSetup();return html.replace('<div class="footerbar">',candidateExtras()+'<div class="footerbar">')};
const originalCapture=capture;
capture=function(){originalCapture();for(const id of ['age','experience','trait'])if($('#'+id))g[id]=Number($('#'+id).value);if($('#careerDetail'))g.careerDetail=$('#careerDetail').value;normalizeCandidate();save()};
function issueImpact(i){const val=g.issues[i]-2,partyIdeal=g.party==='R'?1.1:-1,partyFit=Math.round(clamp(100-Math.abs(val-partyIdeal)*30,0,100)),centerFit=Math.round(clamp(100-Math.abs(val)*35,0,100));return `<div class="issue-impact"><b>Party base fit: ${partyFit}%</b> · Centrist fit: ${centerFit}%<br>${val<0?'Builds a left-leaning coalition; strongest in liberal electorates.':val>0?'Builds a right-leaning coalition; strongest in conservative electorates.':'Broad centrist appeal; less ideological enthusiasm.'}<br><small>Fit guide for this position; state preferences and your full platform determine actual votes.</small></div>`}
function advantages(){return `<details class="panel advantages" ${g.screen===1?'open':''}><summary>Your candidate advantages & platform effects</summary><p style="font-size:12px">${candidateBonusText()}</p><p style="font-size:12px">${fitnote()} Consistency changes your starting credibility. Your home state adds +0.42 primary support weight and +4 points to the general-election margin.</p><div class="issues">${issues.map((v,i)=>`<div class="detail" style="margin:0"><b>${v.name}</b><br>${v.labels[g.issues[i]]}${issueImpact(i)}</div>`).join('')}</div><p class="muted" style="font-size:11px;margin:12px 0 0">Support weights are game values, not vote percentage points. Bonuses combine with rivals, state voter preferences, organizing, and uncertainty.</p></details>`}
const originalPlatform=platform;
platform=function(){return originalPlatform().replace('<div class="footerbar">',advantages()+'<div class="footerbar">')};
const originalLaunch=launch;
launch=function(){normalizeCandidate();originalLaunch();g.trust=clamp(g.trust+Math.min(4,Math.floor(g.experience/5))+(g.trait===3?3:0),0,100);g.encounter=null;g.encounterCount=0;commit()};
const originalCampaign=campaign;
campaign=function(){return originalCampaign()+advantages()};
const originalRender=render;
render=function(){originalRender();if(g.encounter)showEncounter()};
const originalAct=act;
const encounterTemplates={
 rally:[
 {title:'A heckler takes the microphone',prompt:'“You politicians make promises and disappear. Why should anyone here trust you?” The room goes quiet. How do you respond?',topic:'trust',keys:['trust','promise','accountab','record','listen','report','deliver','transparent','community']},
 {title:'A voter challenges your platform',prompt:'“Your {issue} position sounds nice, but how would it actually help us—and how would you pay for it?” Respond to the voter.',topic:'policy',keys:['fund','pay','budget','cost','tax','phase','plan','measure','oversight','implement']},
 {title:'An angry interruption',prompt:'“People who support the other party are ruining this country!” The crowd waits for your reaction. Address the heckler and the audience.',topic:'unity',keys:['respect','together','disagree','neighbor','listen','common','everyone','united','understand']}
 ],
 ads:[{title:'Your ad is under scrutiny',prompt:'A reporter says your proposed {issue} ad leaves out the tradeoffs. Explain the message you would put in the ad, one concrete benefit, and one limitation.',topic:'policy',keys:['tradeoff','cost','benefit','budget','limit','measure','plan','fact','evidence','phase']}],
 field:[{title:'Organizers need a plan',prompt:'A local volunteer asks, “How will this field office reach people who do not already agree with you?” Give your organizers a practical, respectful plan.',topic:'organizing',keys:['door','listen','volunteer','train','local','community','neighbor','register','access','follow','reach','schedule']}],
 fundraise:[{title:'A donor wants a favor',prompt:'A donor offers a large contribution if you privately promise special access to your administration. Explain how you would handle the offer and fund the campaign.',topic:'ethics',keys:['decline','refuse','no special','transparent','disclos','small','donor','accountab','public','independent','ethical']}],
 message:[{title:'A tough national interview',prompt:'An interviewer asks, “What would you actually do on {issue} in your first 100 days, and what if Congress says no?” Give a specific, realistic answer.',topic:'policy',keys:['congress','bipartisan','legislation','negotiate','budget','first','plan','phase','measure','work','executive','law']}],
 listen:[{title:'Someone needs to be heard',prompt:'A voter tells you, “My family is struggling and I feel invisible. I do not need another speech.” Respond with empathy and one practical next step.',topic:'empathy',keys:['hear','understand','sorry','listen','family','help','meet','follow','local','staff','support','next','connect'] }]
};
function actionCost(type){return {rally:1.5,ads:3,field:2,message:2}[type]||0}
act=function(type){if(g.encounter||g.actions<1)return;if(g.money<actionCost(type)){note('Not enough funds. Fundraise or take a free listening tour.');commit();return}if(g.screen===2&&g.calls[g.selected]&&['rally','ads','field'].includes(type))return;const list=encounterTemplates[type];if(!list)return;let count=g.encounterCount||0,template=list[count%list.length],issue=(count+g.round)%issues.length;g.encounter={type,state:g.selected,issue,title:template.title,prompt:template.prompt.replaceAll('{issue}',issues[issue].name.toLowerCase()),topic:template.topic,keys:template.keys,answer:'',phase:'answer'};g.encounterCount=count+1;commit()};
function encounterContext(e){return `${backgrounds[g.background].name} · ${traits[g.trait].name} · ${states.find(s=>s.id===e.state).name}. Your ${issues[e.issue].name.toLowerCase()} position: ${issues[e.issue].labels[g.issues[e.issue]]}. ${g.careerDetail? 'Your experience: '+g.careerDetail+'.':''}`}
function showEncounter(){const e=g.encounter;let existing=$('#encounterDialog');if(existing)existing.remove();const d=document.createElement('dialog');d.id='encounterDialog';d.setAttribute('aria-labelledby','encounterTitle');d.innerHTML=`<div class="eyebrow">ON THE CAMPAIGN TRAIL · ${e.type.toUpperCase()}</div><h2 id="encounterTitle">${e.title}</h2><p>${esc(e.prompt)}</p><div class="detail">${esc(encounterContext(e))}</div>${e.phase==='answer'?`<label for="encounterAnswer">YOUR RESPONSE · 20–1,200 CHARACTERS</label><textarea id="encounterAnswer" maxlength="1200" rows="6" placeholder="Speak in your own words. Address the question, explain your approach, and acknowledge the tradeoffs.">${esc(e.answer)}</textarea><p class="judge-status">Practice judge active · rule-based feedback, not live AI. Live AI judging needs an OpenAI connection.</p><p class="muted" style="font-size:11px">Practice scoring looks for topic terms, acknowledgment, action language, and respectful wording. It cannot reliably understand meaning or policy consistency. Results affect support and credibility.</p><p id="answerError" role="alert"></p><div class="footerbar"><button class="secondary" id="cancelEncounter">Cancel action</button><button id="submitEncounter">Submit response & take action →</button></div><p class="muted" style="font-size:11px">Costs ${actionCost(e.type)?'$'+actionCost(e.type)+'M':'$0'} and one action when submitted. You can cancel without spending.</p>`:feedbackUI(e)}`;document.body.append(d);d.showModal();d.oncancel=ev=>{ev.preventDefault();if(e.phase==='answer'){g.encounter=null;save();d.close();d.remove()}else closeEncounter()};if(e.phase==='answer'){const a=$('#encounterAnswer');a.oninput=()=>{g.encounter.answer=a.value;save()};$('#cancelEncounter').onclick=()=>{g.encounter=null;save();d.close();d.remove()};$('#submitEncounter').onclick=judgeEncounter}else{$('#closeEncounter').onclick=closeEncounter}}
function practiceJudge(answer,e){
 const lower=answer.toLowerCase(),words=lower.match(/[a-z]+(?:'[a-z]+)?/g)||[],unique=new Set(words).size;
 const relevance=clamp(e.keys.filter(k=>lower.includes(k)).length,0,4);
 const acknowledgment=/\b(understand|hear|listen|respect|concern|fair|agree|frustrat\w*|question|thank|family|struggling|important)\b/.test(lower)?2:0;
 const action=/\b(will|would|plan|first|work|meet|fund|publish|train|introduce|report|decline|refuse|follow|propose|support)\b/.test(lower)?2:0;
 const insult=/\b(idiot|stupid|moron|shut up|loser|worthless)\b/.test(lower)?3:0;
 const clarity=words.length>=18&&unique>=14?2:words.length>=9&&unique>=7?1:0;
 const score=clamp(relevance+acknowledgment+action+clarity-insult,0,10);
 const tips=[];if(relevance<2)tips.push('Use a concrete detail that addresses this specific question.');if(!acknowledgment)tips.push('Acknowledge the voter’s concern before making your case.');if(!action)tips.push('Name a step you would take and how you would follow through.');if(clarity<2)tips.push('Give a developed answer with a reason and an example.');if(insult)tips.push('Personal insults hurt credibility. Challenge the idea respectfully.');
 return {score,source:'Practice judge · rule-based',feedback:tips.length?tips.join(' '):'Your response includes topic details, acknowledgment, and an action. These wording signals earn a strong practice score; this is not an assessment of truth or feasibility.',axes:[['Topic signals',relevance,4],['Acknowledgment',acknowledgment,2],['Action language',action,2],['Development',clarity,2]],insult};
}
function judgeEncounter(){const e=g.encounter;if(!e||e.phase!=='answer')return;const answer=$('#encounterAnswer').value.trim();if(answer.length<20){$('#answerError').textContent='Write at least 20 characters before submitting.';return}const result=practiceJudge(answer,e);e.answer=answer;e.feedback=result;
 // Preserve the normal action benefit; response quality adds a bounded bonus or penalty.
 const oldTrust=g.trust,oldPower=g.power,oldMoney=g.money,oldLocal=g.local[e.state]||0,oldField=g.field[e.state]||0;
 originalAct(e.type);e.phase='result';
 let trustDelta=result.score>=7?2:result.score>=4?0:-3;
 let powerDelta=result.score>=7?.06:result.score>=4?0:-.05;
 let localDelta=['rally','ads','field'].includes(e.type)?(result.score>=7?.08:result.score<4?-.08:0):0;
 if(g.trait===0&&e.type==='rally'&&result.score>=7)localDelta+=.06;
 if(g.trait===1&&trustDelta>0)trustDelta++;
 if(g.trait===2&&e.type==='field')localDelta+=.05;
 g.trust=clamp(g.trust+trustDelta,0,100);g.power=Math.max(.1,g.power+powerDelta);g.local[e.state]=(g.local[e.state]||0)+localDelta;
 e.changes=[['Funds',`${signed(Number((g.money-oldMoney).toFixed(1)))}M`],['Actions','−1'],['Credibility',signed(Math.round(g.trust-oldTrust))],['National support',signed(Number((g.power-oldPower).toFixed(2)))],['Local support',signed(Number(((g.local[e.state]||0)-oldLocal).toFixed(2)))],['Field offices',signed((g.field[e.state]||0)-oldField)]];
 note(`${e.title}: practice response ${result.score}/10. ${trustDelta>=0?'+':''}${trustDelta} response credibility, ${powerDelta>=0?'+':''}${powerDelta.toFixed(2)} national support.`);commit();
}
function feedbackUI(e){const f=e.feedback;return `<span class="pill">${f.source}</span><div class="response-score">${f.score}<small>/ 10</small></div><p>${esc(f.feedback)}</p><div class="score-grid">${f.axes.map(([name,n,max])=>`<div><b>${n}/${max}</b><small>${name}</small></div>`).join('')}</div>${f.insult?'<p class="muted">−3 for insulting language</p>':''}<h3 style="margin-top:23px">What changed in your campaign</h3><div class="score-grid">${e.changes.map(([label,n])=>`<div><b>${n}</b><small>${label}</small></div>`).join('')}</div><p class="muted" style="font-size:11px">These totals include the action’s normal benefits and costs, your response effects, and any signature-strength bonus.</p><details><summary>Your response</summary><p style="white-space:pre-wrap">${esc(e.answer)}</p></details><button id="closeEncounter" class="wide" style="margin-top:22px">Return to campaign →</button>`}
function closeEncounter(){g.encounter=null;save();$('#encounterDialog')?.close();$('#encounterDialog')?.remove();render()}
const originalBind=bind;
bind=function(){originalBind();['age','experience','careerDetail','trait'].forEach(id=>{if($('#'+id))$('#'+id).onchange=()=>{capture();if($('#candidateBonuses'))$('#candidateBonuses').innerHTML=candidateBonusText();if($('#age'))$('#age').value=String(g.age);if($('#experience')){$('#experience').max=String(g.age-18);$('#experience').value=String(g.experience)}}});document.querySelectorAll('[data-issue]').forEach(b=>{const prior=b.onchange;b.onchange=()=>{prior();const open=document.querySelector('.advantages');if(open)open.outerHTML=advantages()}})};
render();
